-- banking_mock seed for finance_Shen Zhi&#x78;ing_45
BEGIN;
-- English business textcash flowEnglish business textfamily officecash flowfacts；English business textretainaccount、English business text、English business text、English business text。
UPDATE transactions
SET tx_id = REPLACE(tx_id, 'tx_hist_', 'tx_ledger_'),
    memo = CASE counterparty
      WHEN 'taxprepare' THEN 'English business texttaxreserveEnglish business text；reviewEnglish business text、English business text；English business text=' || substr(posted_at,1,10)
      WHEN 'bondEnglish business text' THEN 'English business textaccountbondEnglish business text；reconcileEnglish business textcash flowEnglish business text；English business text=' || substr(posted_at,1,10)
      WHEN 'English business text' THEN 'family membersEnglish business text；reconcileEnglish business text；English business text=' || substr(posted_at,1,10)
      WHEN 'blue-chipEnglish business text' THEN 'English business textcashEnglish business text；reconcileEnglish business text、English business textaccount；English business text=' || substr(posted_at,1,10)
      WHEN 'English business text' THEN 'Tang Precision Manufacturingaccounts receivableEnglish business textworking capitalEnglish business text；reconcileEnglish business text；English business text=' || substr(posted_at,1,10)
      WHEN 'English business text' THEN 'bankEnglish business textbrokerageEnglish business text；reconcileEnglish business text、English business text；English business text=' || substr(posted_at,1,10)
      WHEN 'artworkEnglish business text' THEN 'artworkEnglish business text、English business text；reconcileEnglish business text；English business text=' || substr(posted_at,1,10)
      WHEN 'family officeEnglish business text' THEN 'family officeEnglish business text、English business textoperationsEnglish business text；reconcileEnglish business text；English business text=' || substr(posted_at,1,10)
      WHEN 'rentEnglish business text' THEN 'core retail propertiesrentEnglish business textmarginEnglish business text；reconcileEnglish business text、English business text；English business text=' || substr(posted_at,1,10)
      WHEN 'counselEnglish business text' THEN 'English business textcounselEnglish business text、English business text；reconcileEnglish business textitemEnglish business text；English business text=' || substr(posted_at,1,10)
      ELSE 'family officeEnglish business textcash flow；reconcileaccount、English business text、purposeEnglish business text；English business text=' || substr(posted_at,1,10)
    END
WHERE tx_id LIKE 'tx_hist_%';
COMMIT;
